Here is the commit message:
ocfs2/dlm: fix off-by-one in dlm_match_regions() region
 comparison

The local-vs-remote region comparison loop uses '<=' instead of '<',
causing it to read one entry past the valid range of qr_regions.  The
other loops in the same function correctly use '<'.

Fix the loop condition to use '<' for consistency and correctness.

Link: https://lkml.kernel.org/r/SYBPR01MB78813DA26B50EC5E01F00566AF7BA@SYBPR01MB7881.ausprd01.prod.outlook.com
Fixes: ea2034416b54 ("ocfs2/dlm: Add message DLM_QUERY_REGION")
Signed-off-by: Junrui Luo <moonafterrain@outlook.com>
Reported-by: Yuhao Jiang <danisjiang@gmail.com>
Reviewed-by: Joseph Qi <joseph.qi@linux.alibaba.com>
Cc: Mark Fasheh <mark@fasheh.com>
Cc: Joel Becker <jlbec@evilplan.org>
Cc: Junxiao Bi <junxiao.bi@oracle.com>
Cc: Changwei Ge <gechangwei@live.cn>
Cc: Jun Piao <piaojun@huawei.com>
Cc: Heming Zhao <heming.zhao@suse.com>
Signed-off-by: Andrew Morton <akpm@linux-foundation.org>

Here is the root cause:
The loop condition `j <= qr->qr_numregions` iterates one extra time beyond the valid array indices (0 to qr->qr_numregions-1), causing an out-of-bounds read of `qr->qr_regions[qr->qr_numregions]`, which leads to incorrect region comparison and potential memory access issues.

Here is the patch:

 static int dlm_match_regions(struct dlm_ctxt *dlm,
 			     struct dlm_query_region *qr,
 			     char *local, int locallen)
 {
 	char *remote = qr->qr_regions;
 	char *l, *r;
 	int localnr, i, j, foundit;
 	int status = 0;

 	if (!o2hb_global_heartbeat_active()) {
 		if (qr->qr_numregions) {
 			mlog(ML_ERROR, "Domain %s: Joining node %d has global "
 			     "heartbeat enabled but local node %d does not\n",
 			     qr->qr_domain, qr->qr_node, dlm->node_num);
 			status = -EINVAL;
 		}
 		goto bail;
 	}

 	if (o2hb_global_heartbeat_active() && !qr->qr_numregions) {
 		mlog(ML_ERROR, "Domain %s: Local node %d has global "
 		     "heartbeat enabled but joining node %d does not\n",
 		     qr->qr_domain, dlm->node_num, qr->qr_node);
 		status = -EINVAL;
 		goto bail;
 	}

 	if (qr->qr_numregions > O2NM_MAX_REGIONS) {
 		mlog(ML_ERROR, "Domain %s: Joining node %d has invalid "
 		     "number of heartbeat regions %u\n",
 		     qr->qr_domain, qr->qr_node, qr->qr_numregions);
 		status = -EINVAL;
 		goto bail;
 	}

 	r = remote;
 	for (i = 0; i < qr->qr_numregions; ++i) {
 		mlog(0, "Region %.*s\n", O2HB_MAX_REGION_NAME_LEN, r);
 		r += O2HB_MAX_REGION_NAME_LEN;
 	}

 	localnr = min(O2NM_MAX_REGIONS, locallen/O2HB_MAX_REGION_NAME_LEN);
 	localnr = o2hb_get_all_regions(local, (u8)localnr);

 	/* compare local regions with remote */
 	l = local;
 	for (i = 0; i < localnr; ++i) {
 		foundit = 0;
 		r = remote;
-		for (j = 0; j <= qr->qr_numregions; ++j) {
+		for (j = 0; j < qr->qr_numregions; ++j) {
 			if (!memcmp(l, r, O2HB_MAX_REGION_NAME_LEN)) {
 				foundit = 1;
 				break;
 			}
 			r += O2HB_MAX_REGION_NAME_LEN;
 		}
 		if (!foundit) {
 			status = -EINVAL;
 			mlog(ML_ERROR, "Domain %s: Region '%.*s' registered "
 			     "in local node %d but not in joining node %d\n",
 			     qr->qr_domain, O2HB_MAX_REGION_NAME_LEN, l,
 			     dlm->node_num, qr->qr_node);
 			goto bail;
 		}
 		l += O2HB_MAX_REGION_NAME_LEN;
 	}

 	/* compare remote with local regions */
 	r = remote;
 	for (i = 0; i < qr->qr_numregions; ++i) {
 		foundit = 0;
 		l = local;
 		for (j = 0; j < localnr; ++j) {
 			if (!memcmp(r, l, O2HB_MAX_REGION_NAME_LEN)) {
 				foundit = 1;
 				break;
 			}
 			l += O2HB_MAX_REGION_NAME_LEN;
 		}
 		if (!foundit) {
 			status = -EINVAL;
 			mlog(ML_ERROR, "Domain %s: Region '%.*s' registered "
 			     "in joining node %d but not in local node %d\n",
 			     qr->qr_domain, O2HB_MAX_REGION_NAME_LEN, r,
 			     qr->qr_node, dlm->node_num);
 			goto bail;
 		}
 		r += O2HB_MAX_REGION_NAME_LEN;
 	}

 bail:
 	return status;
 }



